    amp_nfc_h: "NFC-Tags", amp_nfc_none: "Noch kein Tag mit dieser Spule verknüpft.", amp_nfc_link: "Tag verknüpfen", amp_nfc_wait_p: "Halte das Handy jetzt an den Tag der Spule „{s}“.", amp_nfc_linked: "Tag verknüpft", amp_nfc_taken: "Dieser Tag gehört zur Spule „{n}“. Zu dieser Spule umhängen?", amp_nfc_off: "NFC ist am Handy ausgeschaltet.", amp_nfc_on_btn: "NFC einschalten", amp_nfc_hint: "Danach öffnet das Antippen mit dem Handy diese Spule; im Dialog „Spule zuordnen“ setzt es sie ins Fach. Geht mit jedem Tag, auch den RFID-Tags von Bambu, Creality oder QIDI.", amp_nfc_del: "Entfernen", amp_nfc_unknown_h: "Unbekannter Tag", amp_nfc_unknown_p: "Dieser Tag ist noch mit keiner Spule verknüpft.", amp_nfc_unknown_os: "steht auf dem Tag (OpenSpool)", amp_nfc_pick: "Mit vorhandener Spule verknüpfen", amp_nfc_new: "Neue Spule anlegen", amp_nfc_new_hint: "Spule noch nicht in der App?", amp_nfc_in_slot: "Diese Spule steckt schon in diesem Fach.", amp_nfc_not_listed: "Die Spule zu diesem Tag ist hier nicht wählbar (z. B. aussortiert oder leer).", amp_nfc_unknown_assign: "Dieser Tag ist mit keiner Spule verknüpft. Verknüpfen kannst du ihn in der Spule unter „NFC-Tags“.",
