    amp_cam_note: "Live from your Wi-Fi, straight from the printer – nothing goes to the internet. Tap for full screen.", amp_cam_full: "Tap for full screen", amp_cam_frames: "still frames",
    amp_nfc_h: "NFC tags", amp_nfc_none: "No tag linked to this spool yet.", amp_nfc_link: "Link tag", amp_nfc_wait_p: "Hold your phone against the tag of “{s}” now.", amp_nfc_linked: "Tag linked", amp_nfc_taken: "This tag belongs to “{n}”. Move it to this spool?", amp_nfc_off: "NFC is turned off on this phone.", amp_nfc_on_btn: "Turn on NFC", amp_nfc_hint: "Tapping the tag with your phone then opens this spool; in “Assign spool” it puts it into the slot. Works with any tag, including the RFID tags from Bambu, Creality or QIDI.", amp_nfc_del: "Remove", amp_nfc_unknown_h: "Unknown tag", amp_nfc_unknown_p: "This tag is not linked to a spool yet.", amp_nfc_unknown_os: "on the tag (OpenSpool)", amp_nfc_pick: "Link to an existing spool", amp_nfc_new: "Add new spool", amp_nfc_new_hint: "Spool not in the app yet?", amp_nfc_in_slot: "This spool is already in this slot.", amp_nfc_not_listed: "The spool for this tag can’t be chosen here (e.g. archived or empty).", amp_nfc_unknown_assign: "This tag is not linked to a spool. You can link it in the spool under “NFC tags”.",
