t_err_net: "Pas de connexion à allmyprinters.com.", amp_nt_err_off: "Les notifications sont désactivées dans cet agent (AMP_PUSH=off).", amp_nt_err_not_on: "Les notifications ne sont pas encore activées pour ce téléphone.", amp_nt_err_agent_old: "Votre agent est trop ancien pour les notifications – veuillez le mettre à jour (docker compose pull && docker compose up -d).", amp_nt_err_app_old: "Veuillez mettre à jour l’application pour utiliser les notifications.", amp_nt_err_other: "Cela n’a pas fonctionné ({e}).", amp_news_h: "Nouveautés", amp_news_open: "Voir les nouveautés", amp_news_empty: "Pas encore de nouveautés.", amp_news_err: "Impossible de charger les nouveautés.", amp_news_more: "En savoir plus", amp_news_set: "Réglages des notifications",   // Benachrichtigungen + Neuigkeiten (14.11.2026)
